<template><main class="ssh-page" aria-label="SSH 节点管理">
  <header><div><h1>SSH 节点</h1><p>独立维护部署运维使用的 SSH 连接节点。</p></div><button type="button" data-create @click="openCreate">新建节点</button></header>
  <p v-if="busy" role="status">正在加载…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="!busy&&!nodes.length" data-empty>暂无 SSH 节点</p>
  <table v-else data-node-list><thead><tr><th>名称</th><th>地址</th><th>用户</th><th>凭据</th><th>标签</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="node in nodes" :key="node.id" :data-node-id="node.id"><td>{{node.name}}</td><td>{{node.host}}:{{node.port}}</td><td>{{node.sshUser}}</td><td data-cred>{{node.cred}}</td><td>{{node.tags.join(', ')||'—'}}</td><td>{{node.enabled?'启用':'停用'}} / {{node.heartbeatState||'未知'}}</td><td class="actions"><button type="button" data-probe @click="runProbe(node)">探测</button><button type="button" data-edit @click="openEdit(node)">编辑</button><button type="button" data-delete @click="remove(node)">删除</button></td></tr></tbody></table>
  <p v-if="probeMessage" role="status" data-probe-result>{{probeMessage}}</p>
  <div v-if="editing" class="mask" @click.self="closeEditor"><form role="dialog" aria-modal="true" :aria-label="editingId?'编辑 SSH 节点':'新建 SSH 节点'" @submit.prevent="save"><h2>{{editingId?'编辑 SSH 节点':'新建 SSH 节点'}}</h2><label>名称<input v-model.trim="draft.name" required data-name></label><label>主机<input v-model.trim="draft.host" required data-host></label><label>端口<input v-model.number="draft.port" type="number" min="1" max="65535" required data-port></label><label>SSH 用户<input v-model.trim="draft.sshUser" required data-user></label><label>凭据<input v-model="draft.cred" autocomplete="off" data-cred-input></label><label>标签<input v-model="tagsText" placeholder="逗号分隔" data-tags></label><label class="check"><input v-model="draft.enabled" type="checkbox" data-enabled>启用</label><footer><button type="button" @click="closeEditor">取消</button><button type="submit" data-save>保存</button></footer></form></div>
</main></template>
<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'; import {sshNodeApi,type SshNodeDraft,type SshNodeRecord} from '../services/rebuild/sshNodeApi'
const nodes=ref<SshNodeRecord[]>([]),busy=ref(false),error=ref(''),probeMessage=ref(''),editing=ref(false),editingId=ref<number>(),tagsText=ref('')
const draft=reactive<SshNodeDraft>({name:'',host:'',port:22,sshUser:'root',cred:'',tags:[],enabled:true}); const message=(r:unknown)=>r instanceof Error?r.message:String(r)
async function reload(){busy.value=true;error.value='';try{nodes.value=await sshNodeApi.list()}catch(r){error.value=message(r)}finally{busy.value=false}}
function assign(v?:SshNodeRecord){Object.assign(draft,v?{name:v.name,host:v.host,port:v.port,sshUser:v.sshUser,cred:v.cred,tags:[...v.tags],enabled:v.enabled}:{name:'',host:'',port:22,sshUser:'root',cred:'',tags:[],enabled:true});tagsText.value=draft.tags.join(', ')}
function openCreate(){editingId.value=undefined;assign();editing.value=true} function openEdit(n:SshNodeRecord){editingId.value=n.id;assign(n);editing.value=true} function closeEditor(){editing.value=false}
async function save(){error.value='';draft.tags=tagsText.value.split(',').map(x=>x.trim()).filter(Boolean);try{editingId.value?await sshNodeApi.update(editingId.value,{...draft}):await sshNodeApi.create({...draft});closeEditor();await reload()}catch(r){error.value=message(r)}}
async function remove(n:SshNodeRecord){if(!globalThis.confirm(`删除 SSH 节点“${n.name}”？`))return;try{await sshNodeApi.delete(n.id);await reload()}catch(r){error.value=message(r)}}
async function runProbe(n:SshNodeRecord){probeMessage.value='';try{const x=await sshNodeApi.probe(n.id);probeMessage.value=`${n.name}：${x.ok?'连接成功':'连接失败'}（${x.message}）`}catch(r){error.value=message(r)}} onMounted(reload)
</script>
<style scoped>.ssh-page{max-width:1180px;margin:auto;padding:32px 24px;color:#172033}.ssh-page>header{display:flex;align-items:center;justify-content:space-between}.ssh-page h1{margin:0}.ssh-page header p{color:#64748b}button{cursor:pointer;padding:7px 12px}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;padding:11px;border-bottom:1px solid #e2e8f0}.actions{display:flex;gap:6px}.mask{position:fixed;inset:0;background:#0f172a66;display:grid;place-items:center}.mask form{width:min(480px,calc(100vw - 40px));display:grid;gap:12px;background:white;padding:24px;border-radius:10px}.mask label{display:grid;gap:5px}.mask input{padding:8px}.mask .check{display:flex}.mask footer{display:flex;justify-content:flex-end;gap:8px}</style>
